{
  "schemaVersion": "0.2",
  "slug": "crud-page",
  "name": "CRUD page",
  "status": "experimental",
  "purpose": "List, create, and page records using data-grid, form, dialog, and pagination.",
  "scenarios": [
    "Browse a paged record table",
    "Create a record from a dialog form",
    "Show an empty state when no rows exist"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "pageSize": {
      "type": "number",
      "required": false,
      "description": "Rows shown per page.",
      "default": 5
    },
    "onCreate": {
      "type": "event",
      "required": false,
      "description": "Called after a record is inserted."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Table has one or more rows." },
    { "name": "empty", "description": "No records to show." }
  ],
  "composition": {
    "allowedParents": ["page", "app-shell"],
    "allowedChildren": ["data-grid", "form", "dialog", "pagination", "card", "empty-state", "input", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not ship a second write path besides install-core when distributing this block.",
    "Do not hide create behind an unlabeled icon."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches create, grid, and pagination", "Enter submits the create form"],
    "focus": "Dialog restores trigger focus on close.",
    "labeling": "Grid has an accessible name; create fields have visible labels.",
    "wcag": ["2.1.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Header wraps with flex; grid uses logical inline-size. No viewport media queries.",
    "breakpoints": {
      "compact": "Header stacks; grid scrolls inside its viewport.",
      "medium": "Header sits on one row when space allows.",
      "large": "Header sits on one row when space allows."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "crud-page",
    "states": ["default", "empty"],
    "intents": ["manage-records"]
  }
}

import { Card, DataGrid, Dialog, EmptyState, Form, Input, Pagination, Typography } from '@chameleon-ui/components'
import type { DataGridColumn } from '@chameleon-ui/components'
import { useState, type FormEvent } from 'react'
import { createBlockCopy } from '../copy.js'
import { crudPageLocaleTrees } from './locale-map.js'
import './styles.css'

export interface CrudRecord {
  id: string
  name: string
  status: string
}

export interface CrudPageProps {
  locale?: string
  rows?: CrudRecord[]
  pageSize?: number
  onCreate?: (record: CrudRecord) => void
  className?: string
}

const DEFAULT_ROWS: CrudRecord[] = [
  { id: 'rec-1', name: 'Northwind', status: 'Active' },
  { id: 'rec-2', name: 'Contoso', status: 'Active' },
  { id: 'rec-3', name: 'Fabrikam', status: 'Active' },
]

export function CrudPage({
  locale = 'en',
  rows: initialRows = DEFAULT_ROWS,
  pageSize = 5,
  onCreate,
  className,
}: CrudPageProps) {
  const { t } = createBlockCopy(crudPageLocaleTrees, locale)
  const [rows, setRows] = useState<CrudRecord[]>(initialRows)
  const [page, setPage] = useState(1)
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [error, setError] = useState<string | null>(null)
  const classes = ['cu-block-crud-page', className].filter(Boolean).join(' ')
  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize))
  const currentPage = Math.min(page, totalPages)
  const pageRows = rows.slice((currentPage - 1) * pageSize, currentPage * pageSize)

  const columns: DataGridColumn<CrudRecord>[] = [
    { key: 'name', header: t('crud.colName'), width: 220 },
    { key: 'status', header: t('crud.colStatus'), width: 160 },
  ]

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const trimmed = name.trim()
    if (!trimmed) {
      setError(t('crud.errorRequired'))
      return
    }
    const record: CrudRecord = {
      id: `rec-${Date.now()}`,
      name: trimmed,
      status: t('crud.statusActive'),
    }
    setRows((current) => [record, ...current])
    setName('')
    setError(null)
    setOpen(false)
    setPage(1)
    onCreate?.(record)
  }

  return (
    <section
      className={classes}
      data-ai-role="crud-page"
      data-ai-intent="manage-records"
      data-ai-state={rows.length === 0 ? 'empty' : 'default'}
    >
      <div className="cu-block-crud-page__header">
        <div>
          <Typography variant="heading-1">{t('crud.title')}</Typography>
          <Typography variant="body">{t('crud.subtitle')}</Typography>
          <p className="cu-block-crud-page__meta">{t('crud.itemCount', { count: rows.length })}</p>
        </div>
        <Dialog
          closeLabel={t('crud.close')}
          description={t('crud.dialogDescription')}
          onOpenChange={setOpen}
          open={open}
          title={t('crud.dialogTitle')}
          triggerLabel={t('crud.create')}
        >
          {error ? (
            <p className="cu-block-crud-page__error" role="alert">
              {error}
            </p>
          ) : null}
          <Form onSubmit={handleSubmit} submitLabel={t('crud.submit')}>
            <Input invalid={Boolean(error)} label={t('crud.nameLabel')} onChange={setName} value={name} />
          </Form>
        </Dialog>
      </div>
      <Card padding="md" variant="outlined">
        {rows.length === 0 ? (
          <EmptyState description={t('crud.emptyDescription')} title={t('crud.emptyTitle')} />
        ) : (
          <DataGrid
            columns={columns}
            emptyLabel={t('crud.emptyLabel')}
            getRowId={(row) => row.id}
            height={240}
            label={t('crud.gridLabel')}
            rowHeight={40}
            rows={pageRows}
            width={640}
          />
        )}
      </Card>
      {rows.length > pageSize ? (
        <Pagination currentPage={currentPage} onChange={setPage} totalPages={totalPages} />
      ) : null}
    </section>
  )
}

{
  "slug": "crud-page",
  "type": "registry:block",
  "name": "CRUD page",
  "dependencies": ["card", "data-grid", "dialog", "empty-state", "form", "input", "pagination", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 768,
    "title": "Paged records with create dialog"
  }
}

.cu-block-crud-page {
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-crud-page__header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--cu-space-3);
}

.cu-block-crud-page__meta,
.cu-block-crud-page__error {
  margin-block: var(--cu-space-2) 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-crud-page__error {
  color: var(--cu-color-palette-brand);
}
